import { Component, OnInit } from '@angular/core';
import { Sort } from '@angular/material/sort';
import * as moment from 'moment';
import { ClientTicket, ClientTicketPeriority, ClientTicketStatus, ProcessSupport, ProjectSupport } from 'src/app/interfaces/client-ticket';
import { AccountType, Department, User } from 'src/app/interfaces/user';
import { AuthService } from 'src/app/services/auth.service';
import { FirebaseServiceService } from 'src/app/services/firebase-service.service';


@Component({
  selector: 'app-closed-ticket',
  templateUrl: './closed-ticket.component.html',
  styleUrls: ['./closed-ticket.component.scss']
})
export class ClosedTicketComponent implements OnInit {
  currentUser:User;
  ticketImages:File[];
  urls:string[];
  uploading:boolean = false;
  
  clientProjects:ProjectSupport[];
  clientProcess:ProcessSupport[];
  
  recentClientTickets:ClientTicket[] = [];
  myLimit:number = 5;
  clientTiketStatusEnum = ClientTicketStatus;
  
  searchKey:string = '';
  closeResult: string;

  constructor(private _auth:AuthService,
            private _db:FirebaseServiceService,
) { }

  ngOnInit(): void {
    this._auth.user.subscribe(user=>{
      if(!!user){
        this.currentUser = user;
        if(this.currentUser.accType == AccountType.Client){
          this.getClientRecentTikets();
        }
      }
    })
  }

  getClientRecentTikets(){
    this._db.getClientTicketsByClientKey(this.currentUser.key || '', this.myLimit).subscribe((tickets)=>{      
      this.recentClientTickets = tickets.filter(t=>t.status == ClientTicketStatus.CLOSED).reverse();
    })
  }

  loadMore(){
    this.myLimit += 5;
    this.getClientRecentTikets();
  }

  getTime(dateString) {
    const timestampPositive = Date.parse(dateString)
    return moment(moment.unix(timestampPositive  / 1000)).startOf('minute').fromNow();
  }
  
  getStatus(status: ClientTicketStatus){
    if(status == ClientTicketStatus.STARTED){
      return '#1CCC6D'
    }else if(status == ClientTicketStatus.CLOSED){
      return '#CC1C52'
    }else{
      return '#000'
    }
  }
  getPriority(priority: ClientTicketPeriority){
    if(priority == ClientTicketPeriority.Normal){
      return '#1CCC6D'
    }else if(priority == ClientTicketPeriority.High){
      return '#513982'
    }else if(priority == ClientTicketPeriority.Critical){
      return '#CC1C52'
    }else{
      return '#CC1C52'
    }
  }

  sortData(sort: Sort) {
    const data = this.recentClientTickets.slice();
    if (!sort.active || sort.direction === '') {
      this.recentClientTickets = data;
      return;
    }

    this.recentClientTickets = data.sort((a, b) => {
      const isAsc = sort.direction === 'asc';
      switch (sort.active) {
        case 'title': return compare(a.title, b.title, isAsc);
        // case 'pendingOn': return compare(a.pendingOn, b.pendingOn, isAsc);
        case 'status': return compare(a.status ?a.status : '' , b.status ? b.status : '' , isAsc);
        case 'projectTitle': return compare(a.projectName ? a.projectName : '' , b.projectName ? b.projectName : '', isAsc);
        case 'lastReplied': return compare(this.getTime(a.createdAt) ? this.getTime(a.createdAt) : '', this.getTime(b.createdAt) ? this.getTime(b.createdAt) : '', isAsc);
        default: return 0;
      }
    });
  }

  getTicketName(name:string){
    let newName = ''
    if(name.length < 50){
      return name
    }else{
      newName =`${name.slice(0,50)}...` 
      return newName
    }
  }
}
function compare(a: number | string, b: number | string, isAsc: boolean) {
  return (a < b ? -1 : 1) * (isAsc ? 1 : -1);
}