import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ClientGuard } from 'src/app/services/client.guard';
import { ClientMainComponent } from './Components/client-main/client-main.component';
import { ClientProfileComponent } from './Components/client-profile/client-profile.component';
import { ClientTicketsComponent } from './Components/client-tickets/client-tickets.component';
import { ClosedTicketComponent } from './Components/closed-ticket/closed-ticket.component';
import { TicketDetailsComponent } from './Components/ticket-details/ticket-details.component';

const routes: Routes = [
  { path: '/', component:ClientMainComponent,canActivate:[ClientGuard]},
  { path: 'profile', component:ClientProfileComponent,canActivate:[ClientGuard]},
  { path: 'tickets', component:ClientTicketsComponent,canActivate:[ClientGuard]},
  { path: 'closed', component:ClosedTicketComponent,canActivate:[ClientGuard]},
  { path: 'tickets/:id', component:TicketDetailsComponent,canActivate:[ClientGuard]},
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ClientRoutingModule { }
